#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
const fs = require('node:fs')

class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }

const table = () => ({ t: 'table', m: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isNameChar = (c) => c !== undefined && /^[A-Za-z0-9_-]$/.test(c)

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.c)) this.i++ }
  atEnd() { return this.i >= this.s.length || this.c === '#' || this.c === ';' }
}

function parseBasic(L) {
  L.i++
  let out = ''
  for (;;) {
    if (L.i >= L.s.length) fail('unterminated string')
    const c = L.c
    if (c === '"') { L.i++; return out }
    if (c !== '\\') { out += c; L.i++; continue }
    L.i++
    if (L.i >= L.s.length) fail('unterminated string')
    const e = L.c
    L.i++
    if (e === '"') out += '"'
    else if (e === '\\') out += '\\'
    else if (e === 'n') out += '\n'
    else if (e === 't') out += '\t'
    else if (e === 'r') out += '\r'
    else if (e === '0') out += '\0'
    else if (e === 'u') {
      const h = L.s.slice(L.i, L.i + 4)
      if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
      out += String.fromCharCode(parseInt(h, 16))
      L.i += 4
    } else fail('invalid escape \\' + String.fromCodePoint(L.s.codePointAt(L.i - 1)))
  }
}

function parseLiteral(L) {
  const j = L.s.indexOf("'", L.i + 1)
  if (j < 0) fail('unterminated string')
  const v = L.s.slice(L.i + 1, j)
  L.i = j + 1
  return v
}

function parseName(L) {
  const c = L.c
  if (c === '"') return parseBasic(L)
  if (c === "'") return parseLiteral(L)
  const st = L.i
  while (isNameChar(L.c)) L.i++
  if (L.i === st) fail('expected a name')
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  const names = [parseName(L)]
  for (;;) {
    const save = L.i
    L.ws()
    if (L.c === '.') {
      L.i++
      L.ws()
      names.push(parseName(L))
    } else { L.i = save; return names }
  }
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function walk(tbl, prefix, names, count) {
  let cur = tbl
  for (let k = 0; k < count; k++) {
    const path = prefix.concat(names.slice(0, k + 1)).join('.')
    let ch = cur.m.get(names[k])
    if (ch === undefined) { ch = table(); cur.m.set(names[k], ch) }
    if (ch.t === 'array' && ch.aot) ch = ch.items[ch.items.length - 1]
    else if (ch.t !== 'table') fail(`${path} is not a table`)
    cur = ch
  }
  return cur
}

function assign(tbl, prefix, names, val) {
  const cur = walk(tbl, prefix, names, names.length - 1)
  const last = names[names.length - 1]
  if (cur.m.has(last)) fail(`key ${prefix.concat(names).join('.')} is defined twice`)
  cur.m.set(last, val)
}

function parseValue(L, path) {
  L.ws()
  if (L.atEnd() || L.c === ',' || L.c === ']' || L.c === '}') fail('expected a value')
  const c = L.c
  if (c === '"') return { t: 'string', v: parseBasic(L) }
  if (c === "'") return { t: 'string', v: parseLiteral(L) }
