    L.i++
    const arr = { t: 'array', items: [], aot: false }
    L.ws()
    if (L.c === ']') { L.i++; return arr }
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated array')
      arr.items.push(parseValue(L, path))
      L.ws()
      if (L.c === ',') {
        L.i++
        L.ws()
        if (L.c === ']') { L.i++; return arr }
      } else if (L.c === ']') { L.i++; return arr } else fail('unterminated array')
    }
  }
  if (c === '{') {
    L.i++
    const tb = table()
    L.ws()
    if (L.c === '}') { L.i++; return tb }
    for (;;) {
      L.ws()
      if (L.atEnd()) fail('unterminated inline table')
      const names = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected = in an inline table')
      L.i++
      const v = parseValue(L, path.concat(names))
      assign(tb, path, names, v)
      L.ws()
      if (L.c === ',') L.i++
      else if (L.c === '}') { L.i++; return tb } else fail('unterminated inline table')
    }
  }
  const st = L.i
  while (L.i < L.s.length && !isWs(L.c) && L.c !== ',' && L.c !== ']' && L.c !== '}') L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true' || w === 'false') return { t: 'boolean', v: w === 'true' }
  if (INT.test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
  if (FLOAT.test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
  fail(`invalid value ${w}`)
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = table()
