  let curPath = []
  let n = 0
  try {
    for (const line of lines) {
      n++
      const L = new Line(line)
      L.ws()
      if (L.i >= line.length || L.c === '#' || L.c === ';') continue
      if (L.c === '[') {
        const aot = line[L.i + 1] === '['
        L.i += aot ? 2 : 1
        L.ws()
        const names = parseDotted(L)
        L.ws()
        if (L.c !== ']') fail('unterminated table header')
        L.i++
        if (aot) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        L.ws()
        if (!L.atEnd()) fail('trailing text after a table header')
        const parent = walk(root, [], names, names.length - 1)
        const last = names[names.length - 1]
        const path = names.join('.')
        const ex = parent.m.get(last)
        let t
        if (aot) {
          if (ex === undefined) {
            t = table()
            parent.m.set(last, { t: 'array', items: [t], aot: true })
          } else if (ex.t === 'array' && ex.aot) {
            t = table()
            ex.items.push(t)
          } else fail(`${path} is not an array of tables`)
        } else if (ex === undefined) {
          t = table()
          parent.m.set(last, t)
        } else if (ex.t !== 'table') fail(`${path} is not a table`)
        else if (ex.header) fail(`table ${path} is defined twice`)
        else t = ex
        t.header = true
        cur = t
        curPath = names
        continue
      }
      const names = parseDotted(L)
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = parseValue(L, curPath.concat(names))
      L.ws()
      if (!L.atEnd()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    }
  } catch (e) {
    if (e instanceof ParseError) return { error: `error: line ${n}: ${e.message}\n` }
    throw e
  }
  return { root }
}

function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (m) => [...m.keys()].sort(cmp)

function toJson(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (node.t === 'table') {
    if (!node.m.size) return '{}'
    const parts = sortedKeys(node.m).map((k) => `${pad}${JSON.stringify(k)}: ${toJson(node.m.get(k), ind + 1)}`)
    return `{\n${parts.join(',\n')}\n${end}}`
  }
  if (node.t === 'array') {
    if (!node.items.length) return '[]'
    return `[\n${node.items.map((x) => pad + toJson(x, ind + 1)).join(',\n')}\n${end}]`
  }
  return JSON.stringify(node.v)
}

function keys(node, path, out) {
  if (node.t === 'table') {
    for (const k of sortedKeys(node.m)) {
      const p = path === null ? k : `${path}.${k}`
      const ch = node.m.get(k)
      out.push(`${p} ${ch.t}`)
      keys(ch, p, out)
    }
  } else if (node.t === 'array') {
    node.items.forEach((ch, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${ch.t}`)
      keys(ch, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const res = parse(fs.readFileSync(0, 'utf8'))
if (res.error) {
  process.stderr.write(res.error)
  process.exit(2)
}
if (args[0] === 'json') process.stdout.write(toJson(res.root, 0) + '\n')
else {
  const out = []
  keys(res.root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
