  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') { line++; col = 1 }
    else if (c === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
    return c
  }
  const fail = (l, c, r) => { throw new ScanError(l, c, r) }

  const run = (pred) => {
    let s = ''
    while (i < n && pred(cs[i])) s += adv()
    return s
  }
  // digit run with single underscores between digits
  const digits = (pred) => {
    let s = ''
    if (!pred(cs[i])) return s
    for (;;) {
      s += run(pred)
      if (cs[i] === '_' && pred(cs[i + 1])) s += adv()
      else break
    }
    return s
  }

  while (i < n) {
    const c = cs[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) fail(sl, sc, 'unterminated block comment')
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv(); adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) fail(sl, sc, 'unterminated string')
      adv()
      tokens.push([sl, sc, 'rawstring', JSON.stringify(v)])
      continue
    }
    if (isLetter(c)) {
      const s = run(isIdent)
      tokens.push([sl, sc, KEYWORDS.has(s) ? 'keyword' : 'ident', s])
      continue
    }
