export class UriError extends Error {}

export function parse(s) {
  let scheme = null, authority = null, query = null, fragment = null
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    if (e < 0) { authority = s.slice(2); s = '' } else { authority = s.slice(2, 2 + e); s = s.slice(2 + e) }
  }
  const h = s.indexOf('#')
  if (h >= 0) { fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { query = s.slice(q + 1); s = s.slice(0, q) }
  return { scheme, authority, path: s, query, fragment }
}

function splitAuthority(a) {
  let userinfo = null
  const at = a.lastIndexOf('@')
  if (at >= 0) { userinfo = a.slice(0, at); a = a.slice(at + 1) }
  const c = a.indexOf(':', a.lastIndexOf(']') + 1)
  if (c < 0) return { userinfo, host: a, port: null }
  return { userinfo, host: a.slice(0, c), port: a.slice(c + 1) }
}

export function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg; inp = inp.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s, name) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new UriError(`the ${name} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const lower = s => s.replace(/[A-Z]/g, c => c.toLowerCase())
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function normalize(u) {
  let { scheme, authority, path, query, fragment } = u
  if (scheme !== null) scheme = lower(scheme)
  let ui = null, host = null, port = null
  if (authority !== null) {
    ({ userinfo: ui, host, port } = splitAuthority(authority))
  }
  path = pct(path, 'path')
  if (ui !== null) ui = pct(ui, 'userinfo')
  if (host !== null) host = lower(pct(host, 'host'))
  if (query !== null) query = pct(query, 'query')
  if (fragment !== null) fragment = pct(fragment, 'fragment')
  if (port !== null && (port === '' || (scheme !== null && DEFAULT[scheme] === port))) port = null
  path = removeDots(path)
  let out = ''
