const fail = (n, msg) => Object.assign(new Error(`line ${n}: ${msg}`), { uriError: true })

export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  r.scheme = m[1] ?? null
  r.authority = m[2] ?? null
  r.path = m[3]
  r.query = m[4] ?? null
  r.fragment = m[5] ?? null
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : null
  const hp = a.slice(at + 1)
  const colon = hp.indexOf(':', hp.lastIndexOf(']') + 1)
  // lastIndexOf(']') is -1 when absent, so the search starts at 0
  if (colon < 0) return { userinfo, host: hp, port: null }
  return { userinfo, host: hp.slice(0, colon), port: hp.slice(colon + 1) }
}

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i < 0 ? inp : inp.slice(0, i)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const truncated = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function check(n, r) {
  const a = r.authority === null ? null : splitAuthority(r.authority)
  const parts = [
    ['path', r.path],
    ['userinfo', a?.userinfo ?? null],
    ['host', a?.host ?? null],
    ['query', r.query],
    ['fragment', r.fragment],
  ]
  for (const [name, v] of parts) {
    if (v !== null && truncated(v)) throw fail(n, `the ${name} has a truncated percent-encoding`)
  }
}

function serialize(r) {
  let s = ''
  if (r.scheme !== null) s += r.scheme + ':'
  if (r.authority !== null) s += '//' + r.authority
  s += r.path
  if (r.query !== null) s += '?' + r.query
  if (r.fragment !== null) s += '#' + r.fragment
  return s
}

function normalize(r) {
  const scheme = r.scheme === null ? null : lowerAscii(r.scheme)
  let authority = null
  if (r.authority !== null) {
    const a = splitAuthority(r.authority)
    authority = ''
    if (a.userinfo !== null) authority += pct(a.userinfo) + '@'
    authority += lowerAscii(pct(a.host))
    let port = a.port === null ? null : pct(a.port)
    if (port === '' || (scheme !== null && Object.hasOwn(DEFAULT, scheme) && port === DEFAULT[scheme])) port = null
    if (port !== null) authority += ':' + port
  }
  let path = removeDots(pct(r.path))
  if (authority !== null && path === '') path = '/'
  return {
    scheme,
    authority,
    path,
    query: r.query === null ? null : pct(r.query),
    fragment: r.fragment === null ? null : pct(r.fragment),
  }
}

function resolve(base, ref) {
  const t = { scheme: null, authority: null, path: '', query: null, fragment: ref.fragment }
  if (ref.scheme !== null) {
    Object.assign(t, ref, { path: removeDots(ref.path) })
  } else if (ref.authority !== null) {
    Object.assign(t, ref, { scheme: base.scheme, path: removeDots(ref.path) })
  } else {
    t.scheme = base.scheme
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query ?? base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== null && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}

export function processLines(mode, lines) {
  return lines.map((line, idx) => {
    const n = idx + 1
    if (mode === 'normalize') {
      const r = parse(line)
      check(n, r)
      return serialize(normalize(r))
    }
    const sp = line.indexOf(' ')
    if (sp < 0) throw fail(n, 'expected a base and a reference')
    const base = parse(line.slice(0, sp))
    if (base.scheme === null) throw fail(n, 'the base has no scheme')
    const ref = parse(line.slice(sp + 1))
    const t = resolve(base, ref)
    check(n, t)
    return serialize(normalize(t))
  })
}
