import { readFileSync } from 'node:fs'

const fail = (msg) => {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) fail('error: usage: cli.js rounds|tally')
const mode = args[0]

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

let cands = null
const ballots = []
const nameRe = /^[A-Za-z0-9_-]+$/
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const t = line.split(/\s+/)
  if (t[0] === 'candidates') {
    if (cands !== null || ballots.length) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 2) fail(`error: line ${n}: expected candidates <name>...`)
    const seen = new Set()
    for (const name of t.slice(1)) {
      if (!nameRe.test(name)) fail(`error: line ${n}: invalid candidate name ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is declared twice`)
      seen.add(name)
    }
    cands = t.slice(1)
  } else if (t[0] === 'ballot') {
    if (cands === null) fail(`error: line ${n}: candidates must be declared once, before any ballot`)
    if (t.length < 3) fail(`error: line ${n}: expected ballot <count> <candidate>...`)
    if (!/^[1-9][0-9]*$/.test(t[1])) fail(`error: line ${n}: count must be a positive integer`)
    const seen = new Set()
    for (const name of t.slice(2)) {
      if (!cands.includes(name)) fail(`error: line ${n}: unknown candidate ${name}`)
      if (seen.has(name)) fail(`error: line ${n}: candidate ${name} is repeated`)
      seen.add(name)
    }
    ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
  } else {
    fail(`error: line ${n}: unknown directive ${t[0]}`)
  }
}
if (cands === null) fail('error: no candidates')

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
const grand = ballots.reduce((s, b) => s + b.count, 0n)
const continuing = new Set(cands)
const history = new Map(cands.map((c) => [c, []]))
const out = []
let roundNo = 0
let result = 'no winner'
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0n]))
  let active = 0n
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const order = [...counts.keys()].sort((a, b) => cmp(counts.get(b), counts.get(a)) || cmp(a, b))
  out.push(`round ${roundNo}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${grand - active}`)
  if (active === 0n) break
  const win = order.find((c) => counts.get(c) * 2n > active)
  if (win !== undefined) {
    result = `winner ${win}`
    break
  }
  let pool = [...continuing]
  const min = pool.reduce((m, c) => (counts.get(c) < m ? counts.get(c) : m), counts.get(pool[0]))
  pool = pool.filter((c) => counts.get(c) === min)
  for (let r = 0; r < roundNo && pool.length > 1; r++) {
    const m = pool.reduce((x, c) => (history.get(c)[r] < x ? history.get(c)[r] : x), history.get(pool[0])[r])
    pool = pool.filter((c) => history.get(c)[r] === m)
  }
  const elim = pool.reduce((a, b) => (a > b ? a : b))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + result + '\n')
else process.stdout.write(`rounds ${roundNo}\n${result}\n`)
EOF
