export class ParseError extends Error {}

const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const at = `line ${i + 1}: `
    const w = line.split(/\s+/)
    if (w[0] === 'candidates') {
      if (candidates !== null || ballots.length > 0) throw new ParseError(at + 'candidates must be declared once, before any ballot')
      if (w.length < 2) throw new ParseError(at + 'expected candidates <name>...')
      const seen = new Set()
      for (const n of w.slice(1)) {
        if (!NAME.test(n)) throw new ParseError(at + `invalid candidate name ${n}`)
        if (seen.has(n)) throw new ParseError(at + `candidate ${n} is declared twice`)
        seen.add(n)
      }
      candidates = w.slice(1)
    } else if (w[0] === 'ballot') {
      if (candidates === null) throw new ParseError(at + 'candidates must be declared once, before any ballot')
      if (w.length < 3) throw new ParseError(at + 'expected ballot <count> <candidate>...')
      if (!COUNT.test(w[1])) throw new ParseError(at + 'count must be a positive integer')
      const seen = new Set()
      for (const n of w.slice(2)) {
        if (!candidates.includes(n)) throw new ParseError(at + `unknown candidate ${n}`)
        if (seen.has(n)) throw new ParseError(at + `candidate ${n} is repeated`)
        seen.add(n)
      }
      ballots.push({ count: Number(w[1]), prefs: w.slice(2) })
    } else {
      throw new ParseError(at + `unknown directive ${w[0]}`)
    }
  }
  if (candidates === null) throw new ParseError('no candidates')
  return { candidates, ballots }
}
