export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = [] // Map name -> votes per round
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((n) => [n, 0]))
    let active = 0
    let total = 0
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((n) => continuing.has(n))
      if (c !== undefined) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    history.push(votes)
    const list = [...votes].sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const round = { list, exhausted: total - active, eliminated: null }
    rounds.push(round)
    if (active === 0) return { rounds, winner: null }
    const top = list.find(([, v]) => v * 2 > active)
    if (top) return { rounds, winner: top[0] }
    const min = Math.min(...votes.values())
    let tied = [...votes].filter(([, v]) => v === min).map(([n]) => n)
    while (tied.length > 1) {
      let narrowed = false
      for (const h of history) {
        const vs = tied.map((n) => h.get(n))
        const lo = Math.min(...vs)
        if (vs.some((v) => v !== lo)) {
          tied = tied.filter((n) => h.get(n) === lo)
          narrowed = true
          break
        }
      }
      if (!narrowed) break
    }
    const out = tied.reduce((a, b) => (a > b ? a : b))
    round.eliminated = out
    continuing.delete(out)
  }
}
EOF
