import { readFileSync } from 'node:fs'

const fail = (msg) => { process.stderr.write(msg + '\n'); process.exit(2) }
const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') fail('error: usage: cli.js values|deps')

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ t: 'e', v: e })
const num = (v) => ({ t: 'n', v })

// address: returns {c,r} or null
function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const r = parseInt(m[2], 10)
  if (r < 1) return null
  const L = m[1].toUpperCase()
  const c = L.length === 1 ? L.charCodeAt(0) - 64 : 26 * (L.charCodeAt(0) - 64) + (L.charCodeAt(1) - 64)
  return { c, r }
}
function fmtAddr({ c, r }) {
  const L = c <= 26 ? String.fromCharCode(64 + c) : String.fromCharCode(64 + Math.floor((c - 1) / 26)) + String.fromCharCode(65 + ((c - 1) % 26))
  return L + r
}
const key = (a) => a.c * 1000 + a.r

// ---- tokenizer / parser
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) { toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) { toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue }
    if ((m = /^(<>|<=|>=|[-+*\/^=<>(),:])/.exec(s.slice(i)))) { toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue }
    throw new Error('syntax')
  }
  return toks
}

function parse(src) {
  const toks = tokenize(src)
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].k === 'op' && toks[p].v === v
  const bad = () => { throw new Error('syntax') }
  function cmp() {
    let l = add()
    while (peek() && peek().k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
