  const flush = () => { if (i > bs || j > ss) out.push({ who, bs, be: i, ss, se: j }) }
  while (i < n && j < m) {
    if (base[i] === side[j]) { flush(); i++; j++; bs = i; ss = j }
    else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

