  const c = all[k++]
  const group = [c]
  let end = c.be
  while (k < all.length && all[k].bs <= end) { group.push(all[k]); end = Math.max(end, all[k].be); k++ }
  if (c.bs > pos) reg.push({ stable: base.slice(pos, c.bs) })
  const start = c.bs
  if (group.length === 1) {
    reg.push({ lines: sides[c.who].slice(c.ss, c.se), kind: c.who ? 'theirs' : 'mine' })
  } else {
    const rep = who => {
      const g = group.filter(x => x.who === who)
      if (!g.length) return base.slice(start, end)
      const s = Math.min(...g.map(x => x.ss)) - (Math.min(...g.map(x => x.bs)) - start)
      const e = Math.max(...g.map(x => x.se)) + (end - Math.max(...g.map(x => x.be)))
