    if (eq(m, t)) reg.push({ lines: m, kind: 'both' })
    else if (eq(m, b)) reg.push({ lines: t, kind: 'theirs' })
    else if (eq(t, b)) reg.push({ lines: m, kind: 'mine' })
    else reg.push({ conflict: true, m, b, t })
  }
  pos = end
}
if (pos < base.length) reg.push({ stable: base.slice(pos) })

for (const r of reg) {
  if (r.stable) {
    if (mode[0] === 'regions') out.push(`stable ${r.stable.length}`); else out.push(...r.stable)
  } else if (r.conflict) {
    conflict = true
    if (mode[0] === 'regions') out.push(`conflict mine=${r.m.length} base=${r.b.length} theirs=${r.t.length}`)
