    }
  } else if (mode[0] === 'regions') out.push(`${r.kind} ${r.lines.length}`)
  else out.push(...r.lines)
}
process.stdout.write(out.map(l => l + '\n').join(''))
process.exit(conflict ? 1 : 0)
