import { readFileSync } from 'node:fs'

const fail = (msg, code = 2) => {
  process.stderr.write(msg + '\n')
  process.exit(code)
}
const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const args = process.argv.slice(2)
let workers = 0
if (args.length === 1 && (args[0] === 'waves' || args[0] === 'explain')) {
  // ok
} else if (args.length === 2 && args[0] === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else fail(USAGE)
const mode = args[0]

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)
const input = readFileSync(0, 'utf8')
const lines = input.split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const NAME = /^[A-Za-z0-9_.-]+$/
const cost = new Map()
const deps = new Map()
const depLines = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const line = lines[i].trim()
  if (line === '' || line.startsWith('#')) continue
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!NAME.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], Number(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) if (!NAME.test(x)) fail(`error: line ${n}: invalid task name ${x}`)
    depLines.push(w.slice(1))
  } else fail(`error: line ${n}: unknown directive ${w[0]}`)
}
for (const nm of cost.keys()) deps.set(nm, new Set())
for (const [a, ...ds] of depLines) {
  for (const x of [a, ...ds]) if (!cost.has(x)) fail(`error: unknown task ${x}`)
}
for (const [a, ...ds] of depLines) for (const d of ds) deps.get(a).add(d)

const names = [...cost.keys()].sort(cmp)
const sdeps = new Map(names.map((k) => [k, [...deps.get(k)].sort(cmp)]))

// cycle detection
const state = new Map()
const stack = []
function dfs(u) {
  state.set(u, 1)
  stack.push(u)
  for (const v of sdeps.get(u)) {
    const s = state.get(v)
    if (s === 1) {
      const cyc = stack.slice(stack.indexOf(v)).concat(v)
      fail('error: cycle: ' + cyc.join(' -> '), 3)
    }
    if (!s) dfs(v)
  }
  stack.pop()
  state.set(u, 2)
}
for (const nm of names) if (!state.get(nm)) dfs(nm)

// topological order via memoized recursion (acyclic)
const start = new Map(), finish = new Map(), depth = new Map()
function calc(u) {
  if (finish.has(u)) return
  let s = 0, d = 0
  for (const v of sdeps.get(u)) {
    calc(v)
    s = Math.max(s, finish.get(v))
    d = Math.max(d, depth.get(v) + 1)
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
for (const nm of names) calc(nm)
const total = names.reduce((m, k) => Math.max(m, finish.get(k)), 0)

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const nm of names) (ws[depth.get(nm)] ||= []).push(nm)
  ws.forEach((w, k) => (out += `wave ${k}: ${w.join(' ')}\n`))
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const nm of names) out += `${nm} start=${start.get(nm)} finish=${finish.get(nm)} depth=${depth.get(nm)}\n`
  out += `total ${total}\n`
} else {
  const rev = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of sdeps.get(k)) rev.get(d).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0
    for (const v of rev.get(u)) m = Math.max(m, pr(v))
    prio.set(u, m + cost.get(u))
    return m + cost.get(u)
  }
  for (const k of names) pr(k)
  const order = [...names].sort((a, b) => prio.get(b) - prio.get(a) || cmp(a, b))
  const fin = new Map()
  const freeAt = new Array(workers).fill(0)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0, left = names.length, makespan = 0
  while (left > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((k) => !fin.has(k) && sdeps.get(k).every((d) => fin.has(d) && fin.get(d) <= t))
      if (task === undefined) break
      const f = t + cost.get(task)
      fin.set(task, f)
      freeAt[wi] = f
      runs[wi].push(`${task}@${t}-${f}`)
      makespan = Math.max(makespan, f)
      left--
    }
    if (left === 0) break
    t = Math.min(...freeAt.filter((f) => f > t))
  }
  runs.forEach((r, i) => (out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`))
  out += `makespan ${makespan}\n`
}
process.stdout.write(out)
