import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

class Fail extends Error {}
const NAME = /^[A-Za-z0-9_.\/:-]+$/
const COUNT = /^(0|[1-9][0-9]*)$/

function count(v, field, least) {
  if (!COUNT.test(v) || BigInt(v) < BigInt(least)) throw new Fail(`${field} must be an integer of at least ${least}`)
  return BigInt(v)
}

function run(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const out = []
  const stats = new Map()
  let started = false
  let lastTick = null
  let lineNo = 0
  try {
    for (const raw of lines) {
      lineNo++
      const line = raw.trim()
      if (line === '' || line.startsWith('#')) continue
      const f = line.split(/\s+/)
      const d = f[0]
      if (d === 'bucket' || d === 'window' || d === 'route') {
        if (started) throw new Fail('declarations must come before the first event')
      }
      if (d === 'bucket') {
        if (f.length !== 5) throw new Fail('expected bucket <name> <capacity> <refill> <per>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const capacity = count(f[2], 'capacity', 1)
        const refill = count(f[3], 'refill', 0)
        const per = count(f[4], 'per', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'bucket', capacity, refill, per, st: new Map() })
      } else if (d === 'window') {
        if (f.length !== 4) throw new Fail('expected window <name> <limit> <span>')
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        const limit = count(f[2], 'limit', 0)
        const span = count(f[3], 'span', 1)
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { name: f[1], kind: 'window', limit, span, st: new Map() })
      } else if (d === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        const ps = f.slice(2).map((n) => {
          if (!policies.has(n)) throw new Fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(f[1], ps)
      } else if (d === 'event') {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = count(f[1], 'tick', 0)
        const key = f[2]
        if (!NAME.test(key)) throw new Fail(`invalid key ${key}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${f[1]} is before tick ${lastTick}`)
        started = true
        lastTick = tick
        let best = null
        for (const p of routes.keys()) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
        let denier = null
        if (best !== null) {
          const ps = routes.get(best)
          const states = ps.map((p) => {
            let s = p.st.get(key)
            if (!s) {
              s = p.kind === 'bucket' ? { num: p.capacity * p.per, last: tick } : { ticks: [] }
              p.st.set(key, s)
            }
            if (p.kind === 'bucket') {
              const max = p.capacity * p.per
              s.num += p.refill * (tick - s.last)
              if (s.num > max) s.num = max
              s.last = tick
            } else {
              const cut = tick - p.span
              s.ticks = s.ticks.filter((t) => t > cut)
            }
            return s
          })
          for (let i = 0; i < ps.length && denier === null; i++) {
            const p = ps[i]
            const ok = p.kind === 'bucket' ? states[i].num >= p.per : BigInt(states[i].ticks.length) < p.limit
            if (!ok) denier = p.name
          }
          if (denier === null) {
            ps.forEach((p, i) => {
              if (p.kind === 'bucket') states[i].num -= p.per
              else states[i].ticks.push(tick)
            })
          }
        }
        const c = stats.get(key) || { a: 0, d: 0 }
        if (denier === null) c.a++
        else c.d++
        stats.set(key, c)
        if (mode === 'replay') out.push(denier === null ? `${f[1]} ${key} allow` : `${f[1]} ${key} deny ${denier}`)
      } else {
        throw new Fail(`unknown directive ${d}`)
      }
    }
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: line ${lineNo}: ${e.message}\n`)
    process.exit(2)
  }
  if (mode === 'summary') {
    let a = 0
    let d = 0
    for (const k of [...stats.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
      const c = stats.get(k)
      a += c.a
      d += c.d
      out.push(`${k} allowed=${c.a} denied=${c.d}`)
    }
    out.push(`total allowed=${a} denied=${d}`)
  }
  process.stdout.write(out.length ? out.join('\n') + '\n' : '')
}

