export class ParseError extends Error {}
const fail = (m) => { throw new ParseError(m) }
const isWs = (c) => c === ' ' || c === '\t'
const isNameCh = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)
const newTable = () => ({ t: 'table', map: new Map(), defined: false })

function skip(s, i) { while (isWs(s[i])) i++; return i }
const endish = (c) => c === undefined || c === '#' || c === ';'

function parseString(s, i) {
  const q = s[i]
  i++
  let out = ''
  for (;;) {
    const c = s[i]
    if (c === undefined) fail('unterminated string')
    if (c === q) return [out, i + 1]
    if (q === '"' && c === '\\') {
      const e = s[i + 1]
      if (e === undefined) fail('unterminated string')
      const m = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(m, e)) { out += m[e]; i += 2; continue }
      if (e === 'u') {
        const h = s.slice(i + 2, i + 6)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16)); i += 6; continue
      }
      fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(i + 1)))
    }
    out += c; i++
  }
}

function parseName(s, i) {
  const c = s[i]
  if (c === '"' || c === "'") return parseString(s, i)
  let j = i
  while (isNameCh(s[j])) j++
  if (j === i) fail('expected a name')
  return [s.slice(i, j), j]
}

function parseDotted(s, i) {
  const parts = []
  for (;;) {
    i = skip(s, i)
    let n
    ;[n, i] = parseName(s, i)
    parts.push(n)
    i = skip(s, i)
    if (s[i] === '.') { i++; continue }
    return [parts, i]
  }
}

const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function parseValue(s, i, path) {
  i = skip(s, i)
  const c = s[i]
  if (endish(c) || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"' || c === "'") {
    const [v, j] = parseString(s, i)
    return [{ t: 'string', v }, j]
  }
  if (c === '[') {
    i++
    const items = []
    for (;;) {
      i = skip(s, i)
      if (endish(s[i])) fail('unterminated array')
      if (s[i] === ']') return [{ t: 'array', items, aot: false }, i + 1]
      let v
      ;[v, i] = parseValue(s, i, [...path, `[${items.length}]`])
      items.push(v)
      i = skip(s, i)
      if (s[i] === ',') { i++; continue }
      if (s[i] === ']') return [{ t: 'array', items, aot: false }, i + 1]
      fail('unterminated array')
    }
  }
  if (c === '{') {
    i++
    const tbl = newTable()
    i = skip(s, i)
    if (s[i] === '}') return [tbl, i + 1]
    for (;;) {
      i = skip(s, i)
